 public enum ActionOwner{None,Water,Curiosity,Observe}
 public ActionOwner Owner{get;private set;}public string Explanation{get;private set;}="Watching";
 public readonly WorldEventJournal Journal=new WorldEventJournal();
 public readonly List<HybridTarget> Targets=new List<HybridTarget>();
 public void RegisterObject(CreatureAffordance a,string id){var target=HybridTarget.Bind(a.gameObject,id,HybridTargetKind.Object);Register(target);a.simulationTime=()=>State.time;a.cooldown=State.Cooldown(id);a.rememberCooldown=until=>State.RememberCooldown(id,until);}
 readonly Dictionary<string,HybridTarget> byId=new Dictionary<string,HybridTarget>();readonly List<CreatureCandidate> candidates=new List<CreatureCandidate>();
 Func<SliceState> season;CreatureCuriosity curiosity;CreatureRoutine water;IslandNavigator nav;HumanoidMotion motion;HybridTarget observing,placedAttention;float attentionUntil,nextPlacementNotice;float nextPerception,nextDecision,observeClock,nextNeedCheck;bool suppress,suspended,resume;
 public SliceState Season=>season();public HybridState State=>Season.Hybrid;
 bool WaterRequested=>State.guidance.status==GuidanceStatus.Active&&State.guidance.intention==GuidanceIntent.Help&&(State.guidance.target=="water"||State.guidance.target=="cistern"||Find(State.guidance.target)?.villager?.GetComponent<VillagerRoutine>()?.role==VillagerRoutine.Role.WaterGatherer);
 public void Initialize(CreatureRoutine routine,CreatureCuriosity mind,HumanoidMotion visual,CreatureAffordance[] objects,VillagerRoutine[] villagers,GameObject cistern,CarryItem offering,Func<SliceState> current){
  season=current;water=routine;curiosity=mind;motion=visual;nav=GetComponent<IslandNavigator>();
  for(int i=0;i<villagers.Length;i++)Register(HybridTarget.Bind(villagers[i].gameObject,"villager-"+i,HybridTargetKind.Villager));
  for(int i=0;i<objects.Length;i++){var a=objects[i];var t=a.GetComponent<HybridTarget>()??HybridTarget.Bind(a.gameObject,"object-"+i,HybridTargetKind.Object);Register(t);a.simulationTime=()=>State.time;string id=t.id;a.cooldown=State.Cooldown(id);a.rememberCooldown=until=>State.RememberCooldown(id,until);}
  Register(HybridTarget.Bind(cistern,"cistern",HybridTargetKind.Cistern));Register(HybridTarget.Bind(offering.gameObject,"water",HybridTargetKind.Water));
  if(cistern.GetComponent<Collider>()==null){var renderers=cistern.GetComponentsInChildren<Renderer>();if(renderers.Length>0){var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);var box=cistern.AddComponent<BoxCollider>();box.center=cistern.transform.InverseTransformPoint(bounds.center);box.size=bounds.size;}}
  var cue=cistern.GetComponent<SpatialTarget>()??cistern.AddComponent<SpatialTarget>();cue.invoke=()=>Guide(GuidanceIntent.Help,Find("cistern"));
  var waterCue=offering.GetComponent<SpatialTarget>()??offering.gameObject.AddComponent<SpatialTarget>();waterCue.invoke=()=>Guide(GuidanceIntent.Help,Find("water"));
  curiosity.Completed+=CuriosityCompleted;curiosity.Failed+=CuriosityFailed;water.Completed+=WaterCompleted;resume=State.intention.active;
 }
 public void Register(HybridTarget target){if(byId.ContainsKey(target.id))return;byId.Add(target.id,target);Targets.Add(target);}
 public HybridTarget Find(string id)=>id!=null&&byId.TryGetValue(id,out var t)?t:null;
 public bool NoticePlaced(CarryItem item){
  if(item==null||item.held||item.kind==Offering.Creature||Season.paused||suspended||GetComponent<CarryItem>()?.held==true||State.time<nextPlacementNotice)return false;
  var target=item.GetComponent<HybridTarget>();if(target==null||Find(target.id)!=target)return false;
  if(!CanSeeCue(target))return false;
  placedAttention=target;attentionUntil=State.time+12;nextPlacementNotice=State.time+.5f;NoticeCue(target,"Object placed nearby in front",EvidenceSource.PlayerPlacement);nextPerception=nextDecision=0;
  Journal.Add(State.time,"noticed placement",CreatureAction.InvestigateObject,target.id,"Object placed nearby in front");return true;
 }
 public bool CanReach(HybridTarget target){if(target==null||!target.gameObject.activeInHierarchy)return false;return CanReach(target.transform.position);}
 public bool CanReach(Vector3 at){if(!nav.world.Sample(transform.position,nav.profile,12,out var start)||!nav.world.Sample(at,nav.profile,12,out var end))return false;var path=new NavMeshPath();return NavMesh.CalculatePath(nav.world.ToNav(start),nav.world.ToNav(end),new NavMeshQueryFilter{agentTypeID=nav.profile.id,areaMask=1},path)&&path.status==NavMeshPathStatus.PathComplete;}
 // Preview checks never replace a live suggestion or spend a learning receipt.
 public bool CanGuide(GuidanceIntent intent,HybridTarget target,out string reason){
  reason="";
  if(Season.paused||suspended){reason="Paused";return false;}
  if(target==null||!target.gameObject.activeInHierarchy){reason="Target unavailable";return false;}
  if(!Season.developmentFocus&&Owner==ActionOwner.Water&&Season.water<25&&intent!=GuidanceIntent.Help){reason="Occupied with urgent water assistance";return false;}
  if(target.GetComponent<CarryItem>()?.held==true){reason="Target unavailable while carried";return false;}
  if(intent==GuidanceIntent.Protect&&(target.villager==null||target.villager.Memory.injury<=0)){reason="No credible vulnerability to protect";return false;}
  if(intent==GuidanceIntent.Help&&target.kind==HybridTargetKind.Object&&target.villager==null){reason="No relevant help capability";return false;}
  if(!CanReach(target)){reason="Target unreachable";return false;}
  if(intent==GuidanceIntent.Help&&(target.kind==HybridTargetKind.Cistern||target.kind==HybridTargetKind.Water)&&Season.water>=85){reason="Water problem no longer exists";return false;}
  return true;
 }
 public void CancelGuidance(string reason){if(State.guidance.status!=GuidanceStatus.Active)return;if(Owner==ActionOwner.Observe&&State.intention.target==State.guidance.target)Interrupt(reason);Reject(GuidanceStatus.Abandoned,reason);}
 public bool Guide(GuidanceIntent intent,HybridTarget target){
  if(Season.paused||suspended)return false;var g=State.guidance;if(g.status==GuidanceStatus.Active){Journal.Add(State.time,"guidance superseded",CreatureAction.RespondToGuidance,g.target,"New request");State.Evidence.Add(State.time,EvidenceKind.GuidanceEnded,EvidenceSource.PlayerGuidance,CreatureAction.RespondToGuidance,g.target,"Superseded by a new request",g.evidenceId);if(Owner==ActionOwner.Observe&&State.intention.target==g.target)Interrupt("Guidance superseded");}
  g=State.guidance=new GuidanceState{intention=intent,target=target!=null?target.id:"",requestedAt=State.time,expiresAt=State.time+30,status=GuidanceStatus.Active};
  g.evidenceId=State.Evidence.Add(State.time,EvidenceKind.GuidanceOffered,EvidenceSource.PlayerGuidance,CreatureAction.RespondToGuidance,g.target,intent.ToString());
  if(!CanGuide(intent,target,out var reason)){Reject(GuidanceStatus.Rejected,reason);return false;}
  NoticeGuidance();Journal.Add(State.time,"guidance",CreatureAction.RespondToGuidance,g.target,intent.ToString());nextPerception=nextDecision=0;return true;
 }
 void Reject(GuidanceStatus status,string reason){var g=State.guidance;g.status=status;g.reason=reason;Explanation=reason;Journal.Add(State.time,"guidance "+status,CreatureAction.RespondToGuidance,g.target,reason);State.Evidence.Add(State.time,EvidenceKind.GuidanceEnded,EvidenceSource.PlayerGuidance,CreatureAction.RespondToGuidance,g.target,reason,g.evidenceId);if(status==GuidanceStatus.Rejected||g.noticed)Respond(CreatureResponse.Unavailable,Find(g.target),reason,true);}
 public void Tick(float dt,bool advanceClock=true){
  if(GetComponent<CarryItem>()?.held==true)return;
  if(Season.paused||suspended||dt<=0||float.IsNaN(dt)||float.IsInfinity(dt))return;if(advanceClock)State.time=Mathf.Min(100000000,State.time+dt);
  State.Motivation.Advance(dt);
  AdvanceResponse();
  if(State.guidance.status==GuidanceStatus.Active&&State.time>=State.guidance.expiresAt)Reject(GuidanceStatus.Expired,"Request expired");
  if(State.guidance.status==GuidanceStatus.Active&&Find(State.guidance.target)==null)Reject(GuidanceStatus.Abandoned,"Target unavailable");
  if(State.guidance.status==GuidanceStatus.Active){var g=State.guidance;var target=Find(g.target);bool solved=(g.intention==GuidanceIntent.Protect&&target?.villager!=null&&target.villager.Memory.injury<=0)||(g.intention==GuidanceIntent.Help&&(g.target=="cistern"||g.target=="water")&&Season.water>=85);if(solved){if(Owner==ActionOwner.Observe&&State.intention.target==g.target)Interrupt("Problem no longer exists");Reject(GuidanceStatus.Abandoned,"Problem no longer exists");}}
  if(Owner==ActionOwner.Curiosity&&State.intention.action!=CreatureAction.EatFood&&Season.hunger>.9f&&State.time>=nextNeedCheck){nextNeedCheck=State.time+.5f;foreach(var target in Targets)if(target.affordance?.kind==CreatureAffordance.Kind.Food&&target.affordance.Available&&Vector3.Distance(transform.position,target.transform.position)<=nav.world.Scale*350&&CanReach(target)){Interrupt("Hunger supersedes leisure");nextDecision=State.time;break;}}
  if(Owner!=ActionOwner.None&&State.time>State.intention.deadline)FailAction("Action timed out");
  if(Season.developmentFocus&&Owner==ActionOwner.Water&&!WaterRequested)Interrupt("Exploration focus leaves water in the background");
  if(!Season.developmentFocus&&!Season.Finished&&Season.water<18&&State.intention.action!=CreatureAction.EatFood&&(Owner==ActionOwner.Curiosity||Owner==ActionOwner.Observe)&&water.WaterAvailable)Interrupt("Critical water shortage supersedes leisure");
  if(Owner==ActionOwner.None&&State.time>=nextDecision){nextDecision=State.time+.5f;if(State.time>=nextPerception){Perceive();nextPerception=State.time+.25f;}
   CreatureCandidate choice=null;if(resume){resume=false;var prior=State.intention;foreach(var c in candidates)if(c.action==prior.action&&c.target==prior.target&&c.feasible&&prior.deadline>State.time){choice=c;c.timeout=Mathf.Max(1,prior.deadline-State.time);break;}State.intention.active=false;if(choice==null)Journal.Add(State.time,"resume abandoned",prior.action,prior.target,"Saved intention no longer feasible");}
   for(int tries=0;tries<4;tries++){if(choice==null)choice=CreatureDecisionModel.Select(candidates,State.seed,State.decisions);if(choice==null)break;var target=Find(choice.target);if(choice.action==CreatureAction.IdleOrObserve||CanReach(target)){BeginAction(choice,target);break;}choice.feasible=false;if(State.guidance.status==GuidanceStatus.Active&&State.guidance.target==choice.target)Reject(GuidanceStatus.Rejected,"Target unreachable");choice=null;}
   State.decisions=Math.Min(100000000,State.decisions+1);
  }
  // Tick curiosity's needs/affect even during water work, but disable its separate selector.
  curiosity.Tick(dt,Season,false);
  if(Owner==ActionOwner.Water)water.Tick(dt,false);
  else if(Owner==ActionOwner.Observe){if(observing==null||!observing.gameObject.activeInHierarchy||observing.GetComponent<CarryItem>()?.held==true){FailAction("Observed target unavailable");return;}if(nav.MoveTo(observing.transform.position,water.speed,dt)){motion?.Activity(6);observeClock+=dt;if(observeClock>=2){if(observing.villager!=null){var m=observing.villager.Memory;m.trust=Mathf.Clamp01(m.trust+.04f);m.lastAssistance=State.time;if(State.intention.action==CreatureAction.RespondToGuidance)State.RememberBond(observing.id,true);observing.GetComponent<HumanoidMotion>()?.React();}curiosity.NoticeGreeting(observing.transform);Complete();}}else if(nav.Blocked&&State.time-State.intention.startedAt>5)FailAction("Target unreachable");}
 }
 public void Perceive(){
  candidates.Clear();float shortage=Season.developmentFocus||Season.Finished?0:Mathf.Clamp01((65-Season.water)/45);
  Add(new CreatureCandidate{action=CreatureAction.WaterDelivery,situation=Season.water<65?CreatureSituation.WaterShortage:CreatureSituation.Calm,target="water",feasible=!Season.Finished&&water.WaterAvailable&&(!Season.developmentFocus||WaterRequested),urgency=shortage*2.5f,need=Season.care*.65f,timeout=180,expected="Village water increases"},Find("water"));
  foreach(var t in Targets){var inspiration=t.GetComponent<ConstructionInspiration>();if(inspiration!=null){if(!Season.Building.Knows(inspiration.recipe))Add(new CreatureCandidate{action=CreatureAction.InvestigateObject,situation=CreatureSituation.ConstructionOpportunity,target=t.id,need=.4f,affinity=inspiration.recipe==BuildRecipe.Bench&&GetComponent<CreatureConstructionLearning>()?.BenchRequested==true?.75f:0,novelty=.9f,timeout=120,expected="Observe a building idea"},t);continue;}var a=t.affordance;if(a==null){if(t==placedAttention&&State.time<attentionUntil&&t.GetComponent<CarryItem>()?.CanGrab==true)Add(new CreatureCandidate{action=CreatureAction.InvestigateObject,situation=CreatureSituation.PlayOpportunity,target=t.id,need=.3f,novelty=.4f,timeout=30,expected="Inspect the placed resource"},t);continue;}if(!a.Available)continue;float distance=Vector3.Distance(transform.position,t.transform.position)/nav.world.Scale;if(distance>350)continue;
   var ball=a.GetComponent<BeachBall>();ball?.RefreshPlaymate();
   var action=a.kind==CreatureAffordance.Kind.Food?CreatureAction.EatFood:a.kind==CreatureAffordance.Kind.Villager?CreatureAction.SocialInteraction:a.GetComponent<ConstructionBlock>()!=null?CreatureAction.ConstructionPlay:CreatureAction.PlayWithToy;
   var situation=action==CreatureAction.EatFood?CreatureSituation.Hungry:action==CreatureAction.SocialInteraction||a.SharedReady||ball?.Inviting==true||ball?.ProspectivePlayer!=null?CreatureSituation.SafeContact:action==CreatureAction.ConstructionPlay?CreatureSituation.ConstructionOpportunity:CreatureSituation.PlayOpportunity;
   var tree=a.GetComponent<ThrowableTree>();var block=a.GetComponent<ConstructionBlock>();if(block!=null&&GetComponent<CreatureConstructionLearning>()?.Memory.Knows(block.Site.Recipe)==false)continue;
   Add(new CreatureCandidate{action=action,situation=situation,target=t.id,feasible=!(shortage>=1&&action!=CreatureAction.EatFood),urgency=ball?.FetchReady==true?.55f:ball?.Inviting==true?.35f:ball?.ProspectivePlayer!=null?.15f:block?.Site.Requester?.ShowingBuildingNeed==true?.5f:0,need=action==CreatureAction.EatFood?Season.hunger:action==CreatureAction.SocialInteraction?Season.socialPreference*.65f:Season.playPreference*(tree!=null?.2f:block!=null?.7f:.65f),affinity=ball?.FetchReady==true?.3f+Season.WorldPlay.fetchFun*.7f:ball?.Inviting==true?.3f+Season.WorldPlay.rallyFun*.35f:ball?.ProspectivePlayer!=null?.2f+Season.WorldPlay.rallyFun*.25f:a.SharedReady?.55f+a.host.Attraction*.35f:t.villager!=null?t.villager.Attraction*.35f:0,risk=tree!=null?.25f+Season.WorldPlay.Trees.caution*.3f:0,novelty=(tree!=null?.25f:block!=null?.55f:.5f)/(1+a.discoveries),timeout=tree!=null?90:ball?.FetchReady==true?120:block?.Site.IsBridge==true||a.GetComponentInParent<DiscoveryPoint>()!=null?180:a.GetComponent<VillageTributeProp>()!=null?120:a.GetComponent<BeachBall>()!=null?60:30,expected=a.SharedReady?"Share an invited experience":"Safe interaction"},t);
  }
   var g=State.guidance;if(g.status==GuidanceStatus.Active){var t=Find(g.target);if(t!=null){if(g.intention==GuidanceIntent.Investigate||g.intention==GuidanceIntent.Protect||(g.intention==GuidanceIntent.Help&&t.villager!=null))Add(new CreatureCandidate{action=g.intention==GuidanceIntent.Investigate?CreatureAction.InvestigateObject:CreatureAction.RespondToGuidance,situation=t.GetComponent<ConstructionInspiration>()!=null?CreatureSituation.ConstructionOpportunity:g.intention==GuidanceIntent.Investigate&&t.villager==null?CreatureSituation.PlayOpportunity:CreatureSituation.HelpRequested,target=t.id,need=.3f,guidance=.95f,timeout=90,expected=g.intention==GuidanceIntent.Protect?"Attend a vulnerable villager without moving them":"Inspect target"},t);}}
  candidates.Add(new CreatureCandidate{action=CreatureAction.IdleOrObserve,situation=CreatureSituation.Calm,target="",need=.1f,timeout=2,expected="Observe"});
 }
 void Add(CreatureCandidate c,HybridTarget t){c.feasible&=t!=null&&t.gameObject.activeInHierarchy;var partner=t?.villager??t?.affordance?.host??t?.GetComponent<BeachBall>()?.Player?.GetComponent<VillagerSocial>()??t?.GetComponent<BeachBall>()?.ProspectivePlayer?.GetComponent<VillagerSocial>();if(partner!=null)c.affinity+=(State.PlaymateAffinity(partner.GetComponent<HybridTarget>().id)-.5f)*.5f;c.attention=t==placedAttention&&State.time<attentionUntil?Mathf.Clamp01((attentionUntil-State.time)/12)*.9f:0;c.motivation=State.Motivation.Bias(c.action,c.novelty,Season.hunger,partner!=null);if(c.action==CreatureAction.EatFood&&Season.hunger>.8f)c.urgency+=2; c.learned=State.Preference(c.situation,c.action)*.9f;var interest=State.Interest(c.target);c.interest=((interest?.appeal??.5f)-.5f)*.9f;if(t?.GetComponent<ThrowableTree>()!=null)c.interest+=(Season.WorldPlay.Trees.preference-.5f)*.6f+(Season.WorldPlay.Trees.enjoyment-.25f)*.3f;if(t?.affordance?.SharedReady==true&&t.GetComponent<SharedRhythm>()!=null)c.interest+=(Season.WorldPlay.rhythmFun-.5f)*.6f;var playBall=t?.GetComponent<BeachBall>();if(playBall?.Bowling?.CanImitate(transform.position)==true){c.interest+=.25f+(Season.WorldPlay.Bowling.preference-.5f)*.5f;c.attention=Mathf.Max(c.attention,playBall.Bowling.DemonstrationBias);}if(playBall!=null&&(playBall.Inviting||playBall.ProspectivePlayer!=null))c.interest+=(Season.WorldPlay.GentleBall.preference-.5f)*.6f; if(t?.GetComponent<BeachBall>()?.Inviting==true)c.interest+=((State.Interest(BeachBall.RallyInterest)?.appeal??.5f)-.5f)*.5f;if(interest!=null&&State.time-interest.lastUsed<35)c.switching=.3f;c.travel=t!=null?Mathf.Clamp01(Vector3.Distance(transform.position,t.transform.position)/(nav.world.Scale*350))*.55f:0;var g=State.guidance;if(g.status==GuidanceStatus.Active&&(c.target==g.target||(c.action==CreatureAction.WaterDelivery&&g.intention==GuidanceIntent.Help&&(g.target=="cistern"||g.target=="water"||Find(g.target)?.villager?.GetComponent<VillagerRoutine>()?.role=