  if(Owner==ActionOwner.Observe)curiosity.RememberObservation(Season);
  if((intent.action==CreatureAction.WaterDelivery||intent.action==CreatureAction.SocialInteraction||(intent.action==CreatureAction.RespondToGuidance&&Find(intent.target)?.villager!=null))&&State.time-State.lastBenefit>=8){State.energy=Mathf.Min(100,State.energy+1);State.lastBenefit=State.time;}
  var g=State.guidance;if(g.status==GuidanceStatus.Active&&(g.target==intent.target||(intent.action==CreatureAction.WaterDelivery&&g.intention==GuidanceIntent.Help&&(g.target=="water"||g.target=="cistern"||Find(g.target)?.villager?.GetComponent<VillagerRoutine>()?.role==VillagerRoutine.Role.WaterGatherer))))g.status=GuidanceStatus.Completed;
  State.Motivation.Complete(intent.action,partner.Length>0);
  intent.active=false;Owner=ActionOwner.None;observing=null;motion?.LookAt(null);motion?.Activity(0);nav.ResetRoute();nextDecision=State.time+.5f;nextPerception=0;
 }
 public bool Feedback(bool positive){if(Season.paused||suspended)return false;bool learned=State.Reinforce(positive);if(learned)curiosity.PrepareFeedback(State.receipt,Season,Find(State.receipt.target)?.villager);curiosity.Feedback(positive,learned);if(learned){var partner=State.receipt.partner.Length>0?State.receipt.partner:Find(State.receipt.target)?.villager?.GetComponent<HybridTarget>()?.id;State.TeachBond(partner,positive);if(State.receipt.partner.Length>0)Find(State.receipt.partner)?.villager?.Feedback(positive);}if(learned&&State.receipt.action==CreatureAction.PlayWithToy&&Find(State.receipt.target)?.GetComponent<ThrowableTree>()!=null)Season.WorldPlay.Trees.preference=Mathf.Clamp01(Season.WorldPlay.Trees.preference+(positive?.12f:-.12f));if(learned&&State.receipt.bowling)Season.WorldPlay.Bowling.preference=Mathf.Clamp01(Season.WorldPlay.Bowling.preference+(positive?.12f:-.12f));if(learned&&State.receipt.rhythmGame)Season.WorldPlay.rhythmFun=Mathf.Clamp01(Season.WorldPlay.rhythmFun+(positive?.12f:-.12f));if(learned&&State.receipt.gentleRally)Season.WorldPlay.GentleBall.Reinforce(positive);if(learned&&State.receipt.fetched)Season.WorldPlay.fetchFun=Mathf.Clamp01(Season.WorldPlay.fetchFun+(positive?.12f:-.12f));if(learned&&State.receipt.action==CreatureAction.ConstructionPlay&&State.receipt.constructionRecipe>=0)GetComponent<CreatureConstructionLearning>()?.Reinforce((BuildRecipe)State.receipt.constructionRecipe,positive);Journal.Add(State.time,learned?"reinforced":"feedback without lesson",State.receipt.action,State.receipt.target,positive?"Praise":"Discourage");return learned;}
 public void InvalidateLesson(string reason){State.receipt.eligible=false;curiosity.InvalidateFeedback();Journal.Add(State.time,"lesson cleared",State.receipt.action,State.receipt.target,reason);}
 public void Interrupt(string reason,bool keepIntention=false){if(season==null)return;var prior=State.intention;
  if(prior.active&&!prior.evidenceClosed){State.Evidence.Add(State.time,EvidenceKind.ActionInterrupted,prior.source,prior.action,prior.target,reason,prior.evidenceId,prior.partner,prior.situation);prior.evidenceClosed=true;}
  ResetResponses();suppress=true;curiosity.ResetTask();water.ResetTask();suppress=false;motion?.LookAt(null);motion?.Activity(0);nav.ResetRoute();observing=null;Owner=ActionOwner.None;State.receipt.eligible=false;prior.active=keepIntention&&prior.active;resume=prior.active;Journal.Add(State.time,"interrupted",prior.action,prior.target,reason);Explanation=reason;nextNeedCheck=State.time;nextDecision=State.time+.5f;nextPerception=0;}
 public void Suspend(bool value){if(value&&!suspended)Interrupt("Application suspended",true);suspended=value;}
 public void NewSeason(){Interrupt("New season");resume=false;placedAttention=null;ResetResponses();attentionUntil=nextPlacementNotice=0;nextNeedCheck=0;nextDecision=nextPerception=0;foreach(var t in Targets)if(t.affordance!=null)t.affordance.cooldown=0;}
 void OnDisable(){if(season!=null)Interrupt("Creature disabled");}
 void OnDestroy(){if(curiosity!=null){curiosity.Completed-=CuriosityCompleted;curiosity.Failed-=CuriosityFailed;}if(water!=null)water.Completed-=WaterCompleted;}
}
